module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out,
    output out_n
);
    // Intermediate wires for AND gate outputs
    wire and_ab;
    wire and_cd;

    // First layer: two AND operations using continuous assignments
    assign and_ab = a & b;
    assign and_cd = c & d;

    // Second layer: OR operation combining the AND outputs
    assign out = and_ab | and_cd;

    // Inverted output generated by continuous assignment
    assign out_n = ~out;

endmodule